.digitalfunnel-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #eef2f7 0%, #dce6f0 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.digitalfunnel-sim-header {
    background: linear-gradient(135deg, #1a237e 0%, #283593 50%, #3949ab 100%);
    color: white;
    padding: 30px;
    border-radius: 20px;
    margin-bottom: 25px;
    box-shadow: 0 8px 24px rgba(26,35,126,0.3);
    text-align: center;
}

.digitalfunnel-sim-header h1 {
    margin: 0 0 8px 0;
    font-size: 1.8rem;
    font-weight: 700;
}

.digitalfunnel-sim-header p {
    margin: 0;
    opacity: 0.85;
    font-size: 1rem;
}

.digitalfunnel-sim-period-counter {
    text-align: center;
    font-size: 1.1rem;
    color: #555;
    margin-bottom: 20px;
    font-weight: 600;
}

.digitalfunnel-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 15px;
    margin-bottom: 25px;
}

.digitalfunnel-sim-status-card {
    background: white;
    border-radius: 14px;
    padding: 20px 15px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    text-align: center;
    transition: transform 0.3s ease;
    border-top: 3px solid #3949ab;
}

.digitalfunnel-sim-status-card:hover {
    transform: translateY(-4px);
}

.digitalfunnel-sim-card-brand {
    border-top-color: #7b1fa2;
}

.digitalfunnel-sim-label {
    color: #777;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
}

.digitalfunnel-sim-value {
    font-size: 1.6rem;
    font-weight: 700;
    color: #1a237e;
}

.digitalfunnel-sim-briefing {
    background: white;
    border-radius: 14px;
    padding: 25px;
    margin-bottom: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    border-left: 5px solid #3949ab;
}

.digitalfunnel-sim-briefing h3 {
    margin: 0 0 12px 0;
    color: #1a237e;
    font-size: 1.1rem;
}

.digitalfunnel-sim-event {
    background: linear-gradient(135deg, #fff3e0, #ffe0b2);
    border-radius: 14px;
    padding: 20px 25px;
    margin-bottom: 20px;
    border-left: 5px solid #e65100;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

.digitalfunnel-sim-event h4 {
    margin: 0 0 8px 0;
    color: #bf360c;
}

.digitalfunnel-sim-controls {
    background: white;
    border-radius: 14px;
    padding: 25px;
    margin-bottom: 25px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

.digitalfunnel-sim-controls h3 {
    margin: 0 0 5px 0;
    color: #1a237e;
}

.digitalfunnel-sim-hint {
    color: #888;
    font-size: 0.85rem;
    margin-bottom: 15px;
}

.digitalfunnel-sim-channels {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 12px;
    margin-bottom: 15px;
}

.digitalfunnel-sim-channel-row {
    display: flex;
    align-items: center;
    gap: 10px;
    background: #f8f9fa;
    border-radius: 10px;
    padding: 10px 15px;
}

.digitalfunnel-sim-channel-row label {
    flex: 1;
    font-size: 0.9rem;
    font-weight: 500;
    margin: 0;
    color: #333;
}

.digitalfunnel-sim-channel-row input[type="number"] {
    width: 70px;
    padding: 6px 8px;
    border: 2px solid #ddd;
    border-radius: 8px;
    text-align: center;
    font-weight: 600;
    font-size: 0.95rem;
}

.digitalfunnel-sim-channel-row input[type="number"]:focus {
    border-color: #3949ab;
    outline: none;
}

.digitalfunnel-sim-channel-tag {
    font-size: 0.7rem;
    background: #e8eaf6;
    color: #3949ab;
    padding: 3px 8px;
    border-radius: 12px;
    font-weight: 600;
    white-space: nowrap;
}

.digitalfunnel-sim-total {
    text-align: center;
    font-size: 1.1rem;
    font-weight: 700;
    padding: 10px;
    border-radius: 10px;
    margin-bottom: 20px;
    background: #e8f5e9;
    color: #2e7d32;
    transition: background 0.3s, color 0.3s;
}

.digitalfunnel-sim-total.digitalfunnel-sim-total-error {
    background: #ffebee;
    color: #c62828;
}

.digitalfunnel-sim-brand-slider {
    margin-bottom: 20px;
    text-align: center;
}

.digitalfunnel-sim-brand-slider label {
    display: block;
    font-weight: 600;
    margin-bottom: 8px;
    color: #333;
}

.digitalfunnel-sim-brand-slider input[type="range"] {
    width: 100%;
    max-width: 400px;
}

.digitalfunnel-sim-slider-labels {
    display: flex;
    justify-content: space-between;
    max-width: 420px;
    margin: 5px auto 0;
    font-size: 0.8rem;
    color: #888;
}

.digitalfunnel-sim-slider-labels span:nth-child(2) {
    font-weight: 700;
    color: #3949ab;
    font-size: 0.95rem;
}

.digitalfunnel-sim-actions {
    text-align: center;
}

.digitalfunnel-sim-actions .btn-primary {
    background: #3949ab;
    border-color: #3949ab;
    padding: 10px 40px;
    border-radius: 12px;
    font-weight: 600;
    margin-right: 10px;
}

.digitalfunnel-sim-actions .btn-primary:hover {
    background: #283593;
}

.digitalfunnel-sim-history {
    margin-bottom: 25px;
}

.digitalfunnel-sim-charts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: 20px;
    margin-bottom: 30px;
}

.digitalfunnel-sim-chart-box {
    background: white;
    border-radius: 14px;
    padding: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    min-height: 280px;
}

@media (max-width: 768px) {
    .digitalfunnel-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .digitalfunnel-sim-channels {
        grid-template-columns: 1fr;
    }
    .digitalfunnel-sim-charts {
        grid-template-columns: 1fr;
    }
}

