(function() {
    'use strict';

    class DigitalFunnelAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'DigitalFunnel: Performance Marketing Lab';
            this.version = '1.1.0';

            this.CHANNELS = {
                sem:        { baseEff: 1.80, dimFactor: 0.55, brandWeight: 0.05, perfWeight: 0.90 },
                social:     { baseEff: 1.40, dimFactor: 0.30, brandWeight: 0.35, perfWeight: 0.55 },
                email:      { baseEff: 2.50, dimFactor: 0.40, brandWeight: 0.15, perfWeight: 0.30 },
                content:    { baseEff: 0.85, dimFactor: 0.08, brandWeight: 0.55, perfWeight: 0.25 },
                influencer: { baseEff: 1.20, dimFactor: 0.20, brandWeight: 0.50, perfWeight: 0.35 },
                affiliate:  { baseEff: 1.50, dimFactor: 0.35, brandWeight: 0.05, perfWeight: 0.85 }
            };

            this.ROUNDS = [
                {
                    titleKey: 'r1_title',
                    descKey:  'r1_desc',
                    event: null
                },
                {
                    titleKey: 'r2_title',
                    descKey:  'r2_desc',
                    event: { key: 'r2_event', effect: 'competitor' }
                },
                {
                    titleKey: 'r3_title',
                    descKey:  'r3_desc',
                    event: { key: 'r3_event', effect: 'attribution_vendor' }
                },
                {
                    titleKey: 'r4_title',
                    descKey:  'r4_desc',
                    event: { key: 'r4_event', effect: 'ios_privacy' }
                },
                {
                    titleKey: 'r5_title',
                    descKey:  'r5_desc',
                    event: null
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    monthlyRevenue: 1000000,
                    brandEquity: 40,
                    cac: 28,
                    conversionRate: 2.1,
                    repeatPurchaseRate: 35,
                    clv: 220,
                    totalCustomers: 50000,
                    cumulativeContentBonus: 0,
                    iosPrivacyActive: false,
                    competitorActive: false,
                    revenueHistory: [],
                    brandEquityHistory: [],
                    cacHistory: [],
                    roasHistory: [],
                    clvHistory: [],
                    convRateHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    semPct: 30,
                    socialPct: 25,
                    emailPct: 8,
                    contentPct: 10,
                    influencerPct: 15,
                    affiliatePct: 12,
                    brandFocus: 30
                };
            }
            this._updateBriefing(state);
            this._setupLiveTotal();
        }

        _setupLiveTotal() {
            var ids = ['semInput','socialInput','emailInput','contentInput','influencerInput','affiliateInput'];
            var self = this;
            ids.forEach(function(id) {
                var el = document.getElementById(id);
                if (el) {
                    el.addEventListener('input', function() { self._refreshTotal(); });
                }
            });
            var slider = document.getElementById('brandFocusInput');
            if (slider) {
                slider.addEventListener('input', function() {
                    var v = document.getElementById('brandFocusValue');
                    if (v) v.textContent = slider.value + '%';
                });
            }
            this._refreshTotal();
        }

        _refreshTotal() {
            var ids = ['semInput','socialInput','emailInput','contentInput','influencerInput','affiliateInput'];
            var sum = 0;
            ids.forEach(function(id) {
                var el = document.getElementById(id);
                if (el) sum += parseFloat(el.value) || 0;
            });
            var display = document.getElementById('totalPctDisplay');
            if (display) display.textContent = Math.round(sum);
            var bar = document.getElementById('totalAllocationBar');
            if (bar) {
                if (Math.abs(sum - 100) > 0.01) {
                    bar.classList.add('digitalfunnel-sim-total-error');
                } else {
                    bar.classList.remove('digitalfunnel-sim-total-error');
                }
            }
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl) titleEl.innerHTML = window.mySimulation.t(round.titleKey);

            var textEl = document.getElementById('briefingText');
            if (textEl) textEl.innerHTML = window.mySimulation.t(round.descKey);

            var eventPanel = document.getElementById('eventPanel');
            var eventText = document.getElementById('eventText');
            if (round.event && eventPanel && eventText) {
                eventPanel.style.display = 'block';
                eventText.innerHTML = window.mySimulation.t(round.event.key);
            } else if (eventPanel) {
                eventPanel.style.display = 'none';
            }
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);

            var sem = document.getElementById('semInput');
            var social = document.getElementById('socialInput');
            var email = document.getElementById('emailInput');
            var content = document.getElementById('contentInput');
            var influencer = document.getElementById('influencerInput');
            var affiliate = document.getElementById('affiliateInput');
            var brandSlider = document.getElementById('brandFocusInput');

            if (sem) decisions.semPct = parseFloat(sem.value) || 0;
            if (social) decisions.socialPct = parseFloat(social.value) || 0;
            if (email) decisions.emailPct = parseFloat(email.value) || 0;
            if (content) decisions.contentPct = parseFloat(content.value) || 0;
            if (influencer) decisions.influencerPct = parseFloat(influencer.value) || 0;
            if (affiliate) decisions.affiliatePct = parseFloat(affiliate.value) || 0;
            if (brandSlider) decisions.brandFocus = parseFloat(brandSlider.value) || 0;

            var total = decisions.semPct + decisions.socialPct + decisions.emailPct +
                        decisions.contentPct + decisions.influencerPct + decisions.affiliatePct;

            if (Math.abs(total - 100) > 0.5) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('total_warning'), 'warning'
                );
                return false;
            }

            var vals = [decisions.semPct, decisions.socialPct, decisions.emailPct,
                        decisions.contentPct, decisions.influencerPct, decisions.affiliatePct];
            for (var i = 0; i < vals.length; i++) {
                if (vals[i] < 0 || vals[i] > 100) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('range_warning'), 'warning'
                    );
                    return false;
                }
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;
            var monthlyBudget = 200000;
            var quarterBudget = monthlyBudget * 3;

            if (round === 2) ds.competitorActive = true;
            if (round === 4) ds.iosPrivacyActive = true;

            var brandMult = 1 + (ds.brandEquity - 40) * 0.008;
            if (brandMult < 0.7) brandMult = 0.7;

            var competitorPenalty = ds.competitorActive ? 0.88 : 1.0;

            var allocs = {
                sem: d.semPct,
                social: d.socialPct,
                email: d.emailPct,
                content: d.contentPct,
                influencer: d.influencerPct,
                affiliate: d.affiliatePct
            };

            var brandFocusRatio = d.brandFocus / 100;
            var perfFocusRatio = 1 - brandFocusRatio;

            var totalRevenue = 0;
            var totalBrandDelta = 0;
            var totalNewCustomers = 0;
            var channelResults = {};

            var self = this;
            var channelKeys = ['sem','social','email','content','influencer','affiliate'];

            channelKeys.forEach(function(ch) {
                var pct = allocs[ch] / 100;
                var spend = quarterBudget * pct;
                var cfg = self.CHANNELS[ch];

                var efficiency = cfg.baseEff * (1 - cfg.dimFactor * pct);
                if (efficiency < 0.2) efficiency = 0.2;

                efficiency *= brandMult * competitorPenalty;

                if (ds.iosPrivacyActive && (ch === 'sem' || ch === 'social')) {
                    efficiency *= 0.70;
                }

                if (ch === 'content') {
                    ds.cumulativeContentBonus += pct * 0.12;
                    efficiency += ds.cumulativeContentBonus;
                }

                if (ds.iosPrivacyActive && ch === 'email') {
                    efficiency *= 1.25;
                }

                if (round === 3) {
                    // Attribution vendor migration (r3_event): last-click-inflated channels
                    // (SEM, affiliate) lose measured efficiency as attribution precision drops,
                    // while multi-touch/Shapley analysis validates the under-credited
                    // upper-funnel channels (content, influencer) the briefing calls out.
                    if (ch === 'sem' || ch === 'affiliate') {
                        efficiency *= 0.85;
                    } else if (ch === 'content' || ch === 'influencer') {
                        efficiency *= 1.12;
                    }
                }

                var perfRevenue = spend * efficiency * perfFocusRatio * (cfg.perfWeight / 0.5);
                var brandContrib = spend * brandFocusRatio * cfg.brandWeight * 0.0003;

                var newCust = Math.round(perfRevenue / 45);
                totalRevenue += perfRevenue;
                totalBrandDelta += brandContrib;
                totalNewCustomers += newCust;

                channelResults[ch] = {
                    spend: Math.round(spend),
                    revenue: Math.round(perfRevenue),
                    roas: spend > 0 ? Math.round((perfRevenue / spend) * 100) / 100 : 0
                };
            });

            var brandDecay = 2.5;
            if (ds.competitorActive) brandDecay = 3.5;
            ds.brandEquity = Math.min(95, Math.max(5, ds.brandEquity + totalBrandDelta - brandDecay));
            ds.brandEquity = Math.round(ds.brandEquity * 10) / 10;

            var croBonus = 1.0;
            if (round >= 2) {
                var testingQuality = (d.contentPct + d.emailPct) / 50;
                croBonus = 1 + testingQuality * 0.08;
            }
            totalRevenue *= croBonus;

            if (round === 5) {
                var balance = 1 - Math.abs(brandFocusRatio - 0.45) * 1.5;
                if (balance < 0) balance = 0;
                totalRevenue *= (1 + balance * 0.15);
            }

            ds.monthlyRevenue = Math.round(totalRevenue / 3);
            var effectiveCac = totalNewCustomers > 0 ? quarterBudget / totalNewCustomers : 999;
            ds.cac = Math.round(effectiveCac * 100) / 100;
            ds.totalCustomers += totalNewCustomers;

            var convDelta = (ds.brandEquity - 40) * 0.015 + (croBonus - 1) * 5;
            ds.conversionRate = Math.round((2.1 + convDelta) * 100) / 100;
            if (ds.conversionRate < 0.5) ds.conversionRate = 0.5;

            ds.repeatPurchaseRate = Math.min(65, 35 + (ds.brandEquity - 40) * 0.4 + (d.emailPct / 100) * 12);
            ds.repeatPurchaseRate = Math.round(ds.repeatPurchaseRate * 10) / 10;

            ds.clv = Math.round(45 * (1 + ds.repeatPurchaseRate / 100 * 3.5));

            var roas = quarterBudget > 0 ? Math.round((totalRevenue / quarterBudget) * 100) / 100 : 0;

            ds.revenueHistory.push(ds.monthlyRevenue);
            ds.brandEquityHistory.push(ds.brandEquity);
            ds.cacHistory.push(ds.cac);
            ds.roasHistory.push(roas);
            ds.clvHistory.push(ds.clv);
            ds.convRateHistory.push(ds.conversionRate);

            var results = {
                period: round,
                quarterRevenue: Math.round(totalRevenue),
                monthlyRevenue: ds.monthlyRevenue,
                brandEquity: ds.brandEquity,
                cac: ds.cac,
                roas: roas,
                conversionRate: ds.conversionRate,
                clv: ds.clv,
                newCustomers: totalNewCustomers,
                repeatRate: ds.repeatPurchaseRate
            };

            var selfRef = this;
            setTimeout(function() {
                selfRef._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return results;
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('revenueDisplay', 'domainState.monthlyRevenue',
                function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('brandEquityDisplay', 'domainState.brandEquity',
                function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('cacDisplay', 'domainState.cac',
                function(v) { return '$' + v.toFixed(2); });
            uiManager.bind('convRateDisplay', 'domainState.conversionRate',
                function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('clvDisplay', 'domainState.clv',
                function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('roasDisplay', 'results.roas',
                function(v) { return v ? v.toFixed(2) + 'x' : '—'; });
        }

        getChartConfig() {
            return {
                revenueChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Monthly Revenue ($)',
                            data: [],
                            borderColor: '#3949ab',
                            backgroundColor: 'rgba(57,73,171,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }, {
                            label: 'ROAS',
                            data: [],
                            borderColor: '#43a047',
                            backgroundColor: 'rgba(67,160,71,0.05)',
                            borderWidth: 2,
                            fill: false,
                            tension: 0.3,
                            yAxisID: 'y1'
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'Revenue & ROAS Over Time' } },
                        scales: {
                            y: { beginAtZero: false, position: 'left', title: { display: true, text: 'Revenue ($)' } },
                            y1: { beginAtZero: true, position: 'right', grid: { drawOnChartArea: false }, title: { display: true, text: 'ROAS (x)' } }
                        }
                    }
                },
                brandChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Brand Equity',
                            data: [],
                            borderColor: '#7b1fa2',
                            backgroundColor: 'rgba(123,31,162,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }, {
                            label: 'CAC ($)',
                            data: [],
                            borderColor: '#e53935',
                            backgroundColor: 'rgba(229,57,53,0.05)',
                            borderWidth: 2,
                            fill: false,
                            tension: 0.3,
                            yAxisID: 'y1'
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'Brand Equity & Customer Acquisition Cost' } },
                        scales: {
                            y: { beginAtZero: true, max: 100, position: 'left', title: { display: true, text: 'Brand Equity' } },
                            y1: { beginAtZero: true, position: 'right', grid: { drawOnChartArea: false }, title: { display: true, text: 'CAC ($)' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.revenueHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                revenueChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.revenueHistory },
                        { data: state.domainState.roasHistory }
                    ]
                },
                brandChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.brandEquityHistory },
                        { data: state.domainState.cacHistory }
                    ]
                }
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var round = state.currentPeriod;

            if (results.roas < 1.2) return window.mySimulation.t('hint_low_roas');
            if (state.domainState.brandEquity < 30) return window.mySimulation.t('hint_low_brand');
            if (results.cac > 40) return window.mySimulation.t('hint_high_cac');
            if (round >= 3 && state.decisions.brandFocus < 20) return window.mySimulation.t('hint_brand_neglect');
            if (state.decisions.semPct > 45) return window.mySimulation.t('hint_sem_heavy');
            if (results.roas > 2.5 && state.domainState.brandEquity > 55) return window.mySimulation.t('hint_great');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'decisions.semPct',        label: 'SEM %',       i18nKey: 'col_sem' },
                { key: 'decisions.socialPct',      label: 'Social %',    i18nKey: 'col_social' },
                { key: 'decisions.emailPct',       label: 'Email %',     i18nKey: 'col_email' },
                { key: 'decisions.contentPct',     label: 'Content %',   i18nKey: 'col_content' },
                { key: 'decisions.influencerPct',  label: 'Influencer %',i18nKey: 'col_influencer' },
                { key: 'decisions.brandFocus',     label: 'Brand Focus', i18nKey: 'col_brand_focus', formatter: function(v) { return v + '%'; } },
                { key: 'results.monthlyRevenue',   label: 'Revenue',     i18nKey: 'col_revenue', formatter: function(v) { return '$' + Math.round(v).toLocaleString(); } },
                { key: 'results.roas',             label: 'ROAS',        i18nKey: 'col_roas',    formatter: function(v) { return v.toFixed(2) + 'x'; } },
                { key: 'results.brandEquity',      label: 'Brand Eq.',   i18nKey: 'col_brand_eq' },
                { key: 'results.cac',              label: 'CAC',         i18nKey: 'col_cac',     formatter: function(v) { return '$' + v.toFixed(2); } }
            ];
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var revenues = history.map(function(r) { return r.results ? r.results.monthlyRevenue || 0 : 0; });
            var lastRevenue = revenues[revenues.length - 1];
            // Growth is measured across the campaign (Round 1 -> final), i.e. how much the
            // player grew the paid-media-driven revenue they actually control. The prior
            // baseline of 1,000,000 was the inherited-business seed, which the media model
            // never reproduces, so growth was always ~-80% and every player scored
            // "Developing" regardless of skill. Comparing to the player's own Round-1 result
            // makes the metric meaningful, reachable, and discriminating.
            var firstRevenue = revenues[0] || lastRevenue;
            var revenueGrowth = firstRevenue > 0 ? Math.round(((lastRevenue - firstRevenue) / firstRevenue) * 100) : 0;

            var lastRecord = history[history.length - 1];
            var finalBrand = lastRecord.results ? lastRecord.results.brandEquity || 0 : 0;
            var finalCac = lastRecord.results ? lastRecord.results.cac || 0 : 0;
            var finalClv = lastRecord.results ? lastRecord.results.clv || 0 : 0;

            var avgRoas = history.reduce(function(s, r) { return s + (r.results ? r.results.roas || 0 : 0); }, 0) / history.length;

            var performance = 'Developing';
            var insights = [];

            if (revenueGrowth > 30 && finalBrand > 55 && avgRoas > 1.8) {
                performance = 'Excellent';
                insights.push('Outstanding balance between brand building and performance — sustainable growth achieved.');
            } else if (revenueGrowth > 15 && finalBrand > 45 && avgRoas > 1.4) {
                performance = 'Good';
                insights.push('Solid marketing strategy with room for improvement in brand-performance balance.');
            } else if (revenueGrowth > 0) {
                performance = 'Adequate';
                insights.push('Growth achieved but marketing efficiency or brand equity could be improved.');
            } else {
                insights.push('Revenue declined — consider rebalancing toward both brand building and channel diversification.');
            }

            if (finalBrand < 35) insights.push('Brand equity is low. Increasing brand investment would reduce CAC over time.');
            if (finalCac > 35) insights.push('Customer acquisition cost is high. Diversify channels and invest in brand to lower CAC.');
            if (finalClv > 280) insights.push('Strong customer lifetime value — retention strategy is working well.');

            return {
                revenueGrowth: revenueGrowth + '%',
                finalBrandEquity: finalBrand,
                averageRoas: Math.round(avgRoas * 100) / 100,
                finalCac: '$' + finalCac.toFixed(2),
                finalClv: '$' + finalClv,
                performance: performance,
                insights: insights
            };
        }

